		const typeTotal = tc ? (tc.single || 0) + (tc.multi || 0) + (tc.fill || 0) + (tc.essay || 0) : 0;
		const total = typeTotal > 0 ? typeTotal : options?.totalQuestions || 5;
		const questions = [];
