//#region src/services/ai/proxyClient.ts
/**
* Client gọi AI qua proxy của admin (đợt 25/10).
* Trình duyệt KHÔNG giữ key, KHÔNG gọi thẳng Google/Groq/OpenRouter nữa:
* mọi call đi qua /api/ai/chat cùng origin, kèm JWT auth mới (api/http.ts)
* để proxy verify (Auth API getUser). Failover Gemini → Groq → OpenRouter
* và key đều nằm phía server (Vercel env của admin).
* Response giữ đúng shape Gemini generateContent để vòng lặp tool của
* trợ lý không phải sửa: { candidates: [{ content: { parts } }] }.
*/
async function callAiProxy(body) {
	const token = getAccessToken();
	if (!token) {
		const err = /* @__PURE__ */ new Error("Chưa đăng nhập nên không gọi được AI. Thầy/cô đăng nhập lại giúp em.");
		err.status = 401;
		throw err;
	}
	let res;
	try {
		res = await fetch("/api/ai/chat", {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				Authorization: `Bearer ${token}`
			},
			body: JSON.stringify(body)
		});
	} catch {
		throw /* @__PURE__ */ new Error("Không kết nối được máy chủ AI. Thầy/cô kiểm tra mạng rồi thử lại.");
	}
	let json = null;
	try {
		json = await res.json();
	} catch {
		json = null;
	}
	if (!res.ok) {
		const kind = json?.error?.kind;
		const err = /* @__PURE__ */ new Error(kind === "BAD_REQUEST" ? "Câu hỏi chưa rõ ràng — thầy/cô nói rõ hơn giúp em nhé." : "AI đang bận hoặc hết lượt miễn phí, thử lại sau ít phút.");
		err.status = res.status;
		err.kind = kind;
		err.legs = json?.error?.legs;
		throw err;
	}
	return json;
}
/** Call proxy cho các tác vụ sinh nội dung (1 prompt → text). */
async function callAiProxyText(prompt, systemInstruction) {
	const text = ((await callAiProxy({
		contents: [{
			role: "user",
			parts: [{ text: prompt }]
		}],
		systemInstruction
	}))?.candidates?.[0]?.content?.parts || []).filter((p) => typeof p.text === "string").map((p) => p.text).join("");
	if (!text) throw new Error("AI không trả về nội dung.");
	return text;
}
